from collections import deque
def f(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==bg and not seen[i][j]: seen[i][j]=True; q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and g[a][b]==bg and not seen[a][b]:
                seen[a][b]=True; q.append((a,b))
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]:
                # surrounding non-bg color
                s=set()
                st=[(i,j)]; vis={(i,j)}
                while st:
                    a,b=st.pop()
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<h and 0<=y<w:
                            if g[x][y]!=bg: s.add(g[x][y])
                            elif (x,y) not in vis: vis.add((x,y)); st.append((x,y))
                c=s.pop() if len(s)==1 else 0
                out[i][j]=c^1
    return out

